                # If the code is not -1, get the interval
                interval = categories[code]
                # Get the indexer for the interval
                idx = self.get_indexer([interval])
                # If the indexer is not -1, set it in the indexer array
                if idx[0]!= -1:
                    indexer[i] = idx[0]
    elif not is_object_dtype(target_as_index):
